            aria-describedby="${describedBy}"
          />
          ${helper ? `<p class="field-hint" id="${id}-hint">${helper}</p>` : ''}
          <p class="field-error" id="${errorId}" aria-live="polite"></p>
        </div>
      `;
    }

    function render() {
      app.innerHTML = `
        <header class="support-header">
          <p class="eyebrow">Support</p>
          <h1 id="support-title">Contact our team</h1>
          <p class="support-copy">
            Send us a message and we&apos;ll get back to you as soon as possible.
          </p>
        </header>
        <form id="contact-form" novalidate>
          ${fieldMarkup({
            id: 'full-name',
            label: 'Full name',
            type: 'text',
            placeholder: 'Jane Doe',
            required: true,
            errorId: 'full-name-error'
          })}
          ${fieldMarkup({
            id: 'email-address',
            label: 'Email address',
            type: 'email',
            placeholder: 'jane@example.com',
            required: true,
            errorId: 'email-address-error'
          })}
          ${fieldMarkup({
            id: 'phone-number',
            label: 'Phone number',
            type: 'tel',
            placeholder: '+1 (555) 123-4567',
            required: false,
            helper: 'Optional. Use a format like +1 (555) 123-4567.',
            errorId: 'phone-number-error'
          })}
          <div class="actions">
            <button type="submit">Submit request</button>
          </div>
          <p class="status" id="form-status" aria-live="polite"></p>
        </form>
      `;

      const form = document.getElementById('contact-form');
      const status = document.getElementById('form-status');

      const fields = {
        'full-name': {
          input: document.getElementById('full-name'),
          error: document.getElementById('full-name-error'),
          validate: (value) => value.trim() ? '' : 'Full name is required.'
        },
        'email-address': {
          input: document.getElementById('email-address'),
          error: document.getElementById('email-address-error'),
          validate: (value) => {
            if (!value.trim()) return 'Email address is required.';
            return fields['email-address'].input.validity.valid ? '' : 'Enter a valid email address.';
          }
        },
        'phone-number': {
          input: document.getElementById('phone-number'),
          error: document.getElementById('phone-number-error'),
          validate: (value) => {
            if (!value.trim()) return '';
            return /^[+()\-.\s0-9]{7,}$/.test(value.trim())
              ? ''
              : 'Use a phone number format like +1 (555) 123-4567.';
          }
        }
      };

      function clearMessage(name) {
        fields[name].input.setAttribute('aria-invalid', 'false');
        fields[name].error.textContent = '';
      }

      Object.keys(fields).forEach((name) => {
        fields[name].input.addEventListener('input', () => clearMessage(name));
        fields[name].input.addEventListener('blur', () => {
          if (fields[name].input.value.trim()) {
            const message = fields[name].validate(fields[name].input.value);
            fields[name].error.textContent = message;
            fields[name].input.setAttribute('aria-invalid', message ? 'true' : 'false');
          }
        });
      });

      form.addEventListener('submit', (event) => {
        event.preventDefault();
        let firstInvalid = null;
        let hasErrors = false;

        Object.keys(fields).forEach((name) => {
          const { input, error, validate } = fields[name];
          const message = validate(input.value);
          error.textContent = message;
          input.setAttribute('aria-invalid', message ? 'true' : 'false');
          if (message && !firstInvalid) firstInvalid = input;
          if (message) hasErrors = true;
        });

        if (hasErrors) {
          status.textContent = 'Please fix the highlighted fields and try again.';
          firstInvalid && firstInvalid.focus();
          return;
        }

        status.textContent = 'Your message is ready to send.';
        form.reset();
        Object.keys(fields).forEach(clearMessage);
      });
    }

    render();
  </script>
</body>
</html>
